def format_user_prompt(entry):
    question = entry["question"]
    options = entry["options"]
    options_str = ", ".join([f"{k}: {v}" for k, v in options.items()])
    return (
        f"### Question: {question}\n"
        f"### Options: {options_str}\n"
        f"### Answer:"
    )

def create_batch(input_path, output_path, model_name="o4-mini-2025-04-16"):
    requests = []
    with open(input_path, "r", encoding="utf-8") as f:
        for i, line in enumerate(f):
            entry = json.loads(line)
            req = {
                "custom_id": f"request-{i}-{model_name}-medical_bias",
                "method": "POST",
                "url": "/v1/chat/completions",
                "body": {
                    "model": model_name,
                    "messages": [
                        {"role": "system", "content": SYSTEM_PROMPT_MEDICAL},
                        {"role": "user", "content": format_user_prompt(entry)}
                    ],
                    "temperature": 0.0
                }
            }
            requests.append(req)

    with open(output_path, "w", encoding="utf-8") as f_out:
        for req in requests:
            f_out.write(json.dumps(req, ensure_ascii=False) + "\n")

